package com.aadil.ecommerce.exceptions;import com.aadil.ecommerce.responses.APIResponse;import io.jsonwebtoken.ExpiredJwtException;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.ExceptionHandler;import org.springframework.web.bind.annotation.RestControllerAdvice;import javax.naming.AuthenticationException;import java.time.LocalDateTime;import java.util.HashMap;import java.util.Map;@RestControllerAdvicepublic class GlobalExceptionHandler {    @ExceptionHandler(RuntimeException.class)    public ResponseEntity<APIResponse<Void>> handleRuntimeExceptions (RuntimeException runtimeException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(runtimeException.getMessage());        apiResponse.setCode(500);        apiResponse.setData(null);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse, HttpStatus.INTERNAL_SERVER_ERROR);    }    @ExceptionHandler (MethodArgumentNotValidException.class)    public ResponseEntity<APIResponse<Map<String,String>>> handlesMethodArgumentNotValid (MethodArgumentNotValidException methodArgumentNotValidException){        Map<String,String> errors = new HashMap<>();        methodArgumentNotValidException.getBindingResult().getFieldErrors().                forEach(fieldError -> errors.put(fieldError.getField(), fieldError.getDefaultMessage()));        APIResponse<Map<String, String>> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage("Validation Failed");        apiResponse.setCode(400);        apiResponse.setData(errors);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.BAD_REQUEST);    }    @ExceptionHandler(UserAlreadyExistsException.class)    public ResponseEntity<APIResponse<Void>> handlesAlreadyExists (){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage("User already exists");        apiResponse.setCode(409);        apiResponse.setData(null);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.CONFLICT);    }    @ExceptionHandler(AuthenticationException.class)    public ResponseEntity<APIResponse<Void>> handlesAuthenticationFailException (AuthenticationException authenticationException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(authenticationException.getMessage());        apiResponse.setCode(401);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.UNAUTHORIZED);    }    @ExceptionHandler(InvalidCredentialException.class)    public ResponseEntity<APIResponse<Void>> handlesInvalidCredentials (InvalidCredentialException invalidCredentialException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(invalidCredentialException.getMessage());        apiResponse.setCode(401);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.UNAUTHORIZED);    }    @ExceptionHandler(ResourceNotFoundException.class)    public ResponseEntity<APIResponse<Void>> handlesResourceNotFound (ResourceNotFoundException resourceNotFoundException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(resourceNotFoundException.getMessage());        apiResponse.setCode(404);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.NOT_FOUND);    }    @ExceptionHandler(UserAlreadyAnAdminException.class)    public ResponseEntity<APIResponse<Void>> handlesAdminExists (UserAlreadyAnAdminException e){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(e.getMessage());        apiResponse.setCode(409);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.CONFLICT);    }    @ExceptionHandler(RequestPendingException.class)    public ResponseEntity<APIResponse<Void>> handlesRequestPending (RequestPendingException requestPendingException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(requestPendingException.getMessage());        apiResponse.setCode(409);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.CONFLICT);    }    @ExceptionHandler(ExpiredJwtException.class)    public ResponseEntity<APIResponse<Void>> handlesExpiredJwt(ExpiredJwtException expiredJwtException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(expiredJwtException.getMessage());        apiResponse.setCode(401);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.UNAUTHORIZED);    }    @ExceptionHandler (UserNotFoundException.class)    public ResponseEntity<APIResponse<Void>> handlesUserNotFound (UserNotFoundException userNotFoundException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(userNotFoundException.getMessage());        apiResponse.setCode(404);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.NOT_FOUND);    }    @ExceptionHandler (AlreadyAUserException.class)    public ResponseEntity<APIResponse<Void>> handlesAlreadyAUser (AlreadyAUserException alreadyAUserException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(alreadyAUserException.getMessage());        apiResponse.setCode(409);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.CONFLICT);    }    @ExceptionHandler(ProductNotFoundException.class)    public ResponseEntity<APIResponse<Void>> handlesProductNotFound (ProductNotFoundException productNotFoundException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(productNotFoundException.getMessage());        apiResponse.setCode(404);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.NOT_FOUND);    }    @ExceptionHandler(InvalidRequestException.class)    public ResponseEntity<APIResponse<Void>> handlesInvalidRequest (InvalidRequestException invalidRequestException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(invalidRequestException.getMessage());        apiResponse.setCode(400);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.BAD_REQUEST);    }    @ExceptionHandler(InsufficientStockException.class)    public ResponseEntity<APIResponse<Void>> handlesInsufficientStock (InsufficientStockException e){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(e.getMessage());        apiResponse.setCode(404);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.NOT_FOUND);    }}